import{_ as e,c as r,o as i,a0 as n}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque.","frontmatter":{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque."},"headers":[],"relativePath":"da/blog/pre-shot-routines.md","filePath":"da/blog/pre-shot-routines.md"}');const a=e({name:"da/blog/pre-shot-routines.md"},[["render",function(e,t,a,l,s,o){return i(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="opbygning-af-rutiner-før-optagelse" tabindex="-1">Opbygning af rutiner før optagelse <a class="header-anchor" href="#opbygning-af-rutiner-før-optagelse" aria-label="Permalink to &quot;Opbygning af rutiner før optagelse&quot;">​</a></h1><p>Forskellen mellem et godt kast og et fremragende kast sker ofte, før kuglen forlader din hånd. En veldesignet rutine før kast er dit anker i konkurrencens storm – en pålidelig sekvens, der forbereder dit sind og din krop til optimal præstation.</p><h2 id="hvorfor-rutiner-før-optagelse-er-vigtige" tabindex="-1">Hvorfor rutiner før optagelse er vigtige <a class="header-anchor" href="#hvorfor-rutiner-før-optagelse-er-vigtige" aria-label="Permalink to &quot;Hvorfor rutiner før optagelse er vigtige&quot;">​</a></h2><p>Eliteatleter i alle sportsgrene bruger rutiner før kast. I petanque, hvor hvert kast er diskret, og der kan opbygges pres mellem slagene, tjener rutinerne flere formål:</p><ul><li><strong>Konsistens</strong>: Samme forberedelse fører til mere ensartet udførelse</li><li><strong>Fokus</strong>: Giver dit sind en konstruktiv opgave i stedet for at bekymre dig</li><li><strong>Overgang</strong>: Hjælper dig med at skifte fra at tænke til at handle</li><li><strong>Preshåndtering</strong>: Velkendte handlinger beroliger nervesystemet</li><li><strong>Nulstil</strong>: Sletter det forrige billede fra dit sind</li></ul><h2 id="anatomien-af-en-effektiv-rutine" tabindex="-1">Anatomien af en effektiv rutine <a class="header-anchor" href="#anatomien-af-en-effektiv-rutine" aria-label="Permalink to &quot;Anatomien af en effektiv rutine&quot;">​</a></h2><p>En god rutine før indtagelse har tre faser:</p><h3 id="fase-1-vurdering-5-10-sekunder" tabindex="-1">Fase 1: Vurdering (5-10 sekunder) <a class="header-anchor" href="#fase-1-vurdering-5-10-sekunder" aria-label="Permalink to &quot;Fase 1: Vurdering (5-10 sekunder)&quot;">​</a></h3><ul><li>Læs terrænet</li><li>Visualiser det tilsigtede resultat</li><li>Vælg din kastetype</li><li>Forpligt dig til beslutningen</li></ul><h3 id="fase-2-forberedelse-5-10-sekunder" tabindex="-1">Fase 2: Forberedelse (5-10 sekunder) <a class="header-anchor" href="#fase-2-forberedelse-5-10-sekunder" aria-label="Permalink to &quot;Fase 2: Forberedelse (5-10 sekunder)&quot;">​</a></h3><ul><li>Tag din position</li><li>Find dit greb</li><li>Få ro på din vejrtrækning</li><li>Mærk vægten af kuglen</li></ul><h3 id="fase-3-udførelse-3-5-sekunder" tabindex="-1">Fase 3: Udførelse (3-5 sekunder) <a class="header-anchor" href="#fase-3-udførelse-3-5-sekunder" aria-label="Permalink to &quot;Fase 3: Udførelse (3-5 sekunder)&quot;">​</a></h3><ul><li>Endelig fokus på målet</li><li>Stol på din krop</li><li>Slip fri uden tanke</li><li>Følg op naturligt</li></ul><h2 id="opbygning-af-din-personlige-rutine" tabindex="-1">Opbygning af din personlige rutine <a class="header-anchor" href="#opbygning-af-din-personlige-rutine" aria-label="Permalink to &quot;Opbygning af din personlige rutine&quot;">​</a></h2><h3 id="trin-1-observer-dine-nuværende-mønstre" tabindex="-1">Trin 1: Observer dine nuværende mønstre <a class="header-anchor" href="#trin-1-observer-dine-nuværende-mønstre" aria-label="Permalink to &quot;Trin 1: Observer dine nuværende mønstre&quot;">​</a></h3><p>Før du opretter en ny rutine, så læg mærke til, hvad du allerede gør:</p><ul><li>Hvad gør man før succesfulde kast?</li><li>Hvad ændrer sig, når man er under pres?</li><li>Hvad føles naturligt for dig?</li></ul><h3 id="trin-2-design-din-sekvens" tabindex="-1">Trin 2: Design din sekvens <a class="header-anchor" href="#trin-2-design-din-sekvens" aria-label="Permalink to &quot;Trin 2: Design din sekvens&quot;">​</a></h3><p>Lav en rutine, der inkluderer:</p><p><strong>Fysiske elementer:</strong></p><ul><li>Hvordan du griber cirklen an</li><li>Sådan løfter og holder du kuglen</li><li>Din holdning og positionering</li><li>Et specifikt åndedrætsmønster</li></ul><p><strong>Mentale elementer:</strong></p><ul><li>En visualisering af resultatet</li><li>Et fokusord eller en fokusfrase</li><li>Et forpligtelsespunkt (det øjeblik du beslutter dig for, at &quot;dette er kastet&quot;)</li></ul><h3 id="trin-3-hold-det-enkelt" tabindex="-1">Trin 3: Hold det enkelt <a class="header-anchor" href="#trin-3-hold-det-enkelt" aria-label="Permalink to &quot;Trin 3: Hold det enkelt&quot;">​</a></h3><p>Din rutine bør være:</p><ul><li><strong>Kort nok</strong> til at opretholde trykket (15-25 sekunder i alt)</li><li><strong>Simpel nok</strong> til at huske, når man er stresset</li><li><strong>Fleksibel nok</strong> til at tilpasse sig forskellige situationer</li></ul><h2 id="eksempelrutiner" tabindex="-1">Eksempelrutiner <a class="header-anchor" href="#eksempelrutiner" aria-label="Permalink to &quot;Eksempelrutiner&quot;">​</a></h2><h3 id="pointerens-rutine" tabindex="-1">Pointerens rutine <a class="header-anchor" href="#pointerens-rutine" aria-label="Permalink to &quot;Pointerens rutine&quot;">​</a></h3><ol><li>Stil dig bag cirklen og vurder terrænet</li><li>Visualiser kuglens bane og landingssted</li><li>Træd ind i cirklen, find din holdning</li><li>Tre langsomme vejrtrækninger mens du mærker på kuglen</li><li>Øjnene på målet, slip</li></ol><h3 id="skytterens-rutine" tabindex="-1">Skytterens rutine <a class="header-anchor" href="#skytterens-rutine" aria-label="Permalink to &quot;Skytterens rutine&quot;">​</a></h3><ol><li>Identificér målkuglen, vælg vinklen</li><li>Visualiser effekten og resultatet</li><li>Gå ind i cirklen med et formål</li><li>En dyb indånding, mærk vægten</li><li>Hold blikket rettet mod målet, udfør</li></ol><h2 id="almindelige-fejl-at-undga" tabindex="-1">Almindelige fejl at undgå <a class="header-anchor" href="#almindelige-fejl-at-undga" aria-label="Permalink to &quot;Almindelige fejl at undgå&quot;">​</a></h2><h3 id="for-lang" tabindex="-1">For lang <a class="header-anchor" href="#for-lang" aria-label="Permalink to &quot;For lang&quot;">​</a></h3><p>Hvis din rutine tager mere end 30 sekunder, tænker du for meget. Lange rutiner giver angst mere tid til at opbygge sig.</p><h3 id="for-stiv" tabindex="-1">For stiv <a class="header-anchor" href="#for-stiv" aria-label="Permalink to &quot;For stiv&quot;">​</a></h3><p>Hvis en afbrydelse ødelægger din rutine, er den for skrøbelig. Indbyg fleksibilitet – hvis noget forstyrrer din koncentration, så hav en nulstillingsmekanisme.</p><h3 id="springe-over-under-pres" tabindex="-1">Springe over under pres <a class="header-anchor" href="#springe-over-under-pres" aria-label="Permalink to &quot;Springe over under pres&quot;">​</a></h3><p>Rutinen er vigtigst, når presset er højest. Hvis du opgiver den, når du er stresset, mister du dens beskyttende fordele.</p><h3 id="fokus-pa-mekanik" tabindex="-1">Fokus på mekanik <a class="header-anchor" href="#fokus-pa-mekanik" aria-label="Permalink to &quot;Fokus på mekanik&quot;">​</a></h3><p>Din træningsrutine bør slutte med fokus på resultatet, ikke på teknik. &quot;Ram målet&quot; ikke &quot;hold albuen lige&quot;.</p><h2 id="øvelse-af-din-rutine" tabindex="-1">Øvelse af din rutine <a class="header-anchor" href="#øvelse-af-din-rutine" aria-label="Permalink to &quot;Øvelse af din rutine&quot;">​</a></h2><h3 id="under-træning" tabindex="-1">Under træning <a class="header-anchor" href="#under-træning" aria-label="Permalink to &quot;Under træning&quot;">​</a></h3><ul><li>Brug din fulde rutine til hvert kast, selv de mere afslappede</li><li>Tag tid på dig selv for at sikre konsistens</li><li>Øv dig med distraktioner for at opbygge modstandsdygtighed</li></ul><h3 id="bygningsautomatik" tabindex="-1">Bygningsautomatik <a class="header-anchor" href="#bygningsautomatik" aria-label="Permalink to &quot;Bygningsautomatik&quot;">​</a></h3><p>Målet er, at din rutine bliver automatisk – noget du gør uden at tænke over det. Dette kræver gentagelse:</p><ul><li>100+ kast med samme rutine</li><li>Konsekvent brug i forskellige situationer</li><li>Gradvis eksponering for pres, samtidig med at rutinen opretholdes</li></ul><h2 id="tilpasning-til-konkurrence" tabindex="-1">Tilpasning til konkurrence <a class="header-anchor" href="#tilpasning-til-konkurrence" aria-label="Permalink to &quot;Tilpasning til konkurrence&quot;">​</a></h2><p>I kampe kan din rutine have brug for små justeringer:</p><ul><li><strong>Tidspres</strong>: Hav en forkortet version klar</li><li><strong>Vejrforhold</strong>: Juster de fysiske elementer efter behov</li><li><strong>Øjeblikke med højt tryk</strong>: Sænk farten en smule, øg ikke farten</li></ul><h2 id="nulstillingsrutinen" tabindex="-1">Nulstillingsrutinen <a class="header-anchor" href="#nulstillingsrutinen" aria-label="Permalink to &quot;Nulstillingsrutinen&quot;">​</a></h2><p>Lige så vigtigt er, hvad du gør efter et kast:</p><ol><li><strong>Accepter resultatet</strong> — godt eller dårligt, det er gjort</li><li><strong>Fysisk nulstilling</strong> — træd tilbage, ryst spændinger ud</li><li><strong>Mental nulstilling</strong> — ryd kastet ud af dit sind</li><li><strong>Forbered dig på det næste</strong> — skift fokus til det, der kommer</li></ol><hr><p>| <em>Relateret: <a href="/da/uddannelse/mental-styrke/rutine-før-indtagelse">Guide til rutine før indtagelse</a> | <a href="/da/uddannelse/mental-styrke/håndtering-af-pres">Håndtering af pres</a> | <a href="/da/uddannelse/mindfulness/teknikker">Mindfulness-teknikker</a></em> |</p>',54)])])}]]);export{t as __pageData,a as default};
